public interface CoreAccountInterface {

    fun `agentLab`(`listener`: AgentLabListener): CoreAgentLab

    fun `cancel`()

    /**
     * Delete only the last connected account cache after an explicit sign-out.
     */
    fun `clearLocalData`()

    /**
     * Open only the current account's registry and document cache.
     */
    fun `connect`(`config`: CoreConfig, `listener`: ClientListener): CoreClient

    fun `customAgents`(`listener`: CustomAgentsListener): CoreAgents

    /**
     * Have the computer `device_id`, just connected by code, sign in as
     * this account (#12000): its account key is added to the account.
     * Call it right after `CoreClient::connect_computer`; the computer
     * answers only shortly after the scan. Answers the computer's key.
     */
    suspend fun `linkComputer`(`client`: CoreClient, `deviceId`: kotlin.String): kotlin.String

    fun `projectSharing`(`listener`: SharingListener): CoreSharing

    fun `restore`()

    /**
     * Resume account checks without cancelling a device-code approval in progress.
     */
    fun `revalidate`()

    /**
     * Read the same account history as the desktop without starting an engine.
     */
    fun `savedHistory`(`listener`: SavedHistoryListener): CoreSavedHistory

    /**
     * Explicit credentials are checked by the same SDK and stored by the same controller.
     */
    fun `signInWithCredential`(`credential`: kotlin.String)

    fun `signOut`()

    fun `snapshot`(): AccountSnapshot

    /**
     * A native diagnostic checks only this app/profile/deployment's own entry.
     */
    fun `storedLoginPresent`(): kotlin.Boolean

    fun `voiceAgent`(`listener`: VoiceAgentListener): CoreVoiceAgent

    /**
     * Delete the signed-in account and sign this app out. Call it only
     * after the person confirmed the warning; with `forfeit_balance`,
     * only after they confirmed giving up paid credit.
     */
    suspend fun `deleteAccount`(`forfeitBalance`: kotlin.Boolean): AccountDeletion

    fun `chatHomes`(`client`: CoreClient, `chat`: kotlin.String): CoreChatHomes

    /**
     * The chat answered by OpenAgents, as this phone's account.
     */
    fun `cloudChat`(`listener`: CloudChatListener): CoreCloudChat

    /**
     * Our cloud's current state.
     */
    suspend fun `cloudHost`(): CloudHostView

    /**
     * Start Our cloud (or return the run already going).
     */
    suspend fun `startCloudHost`(): CloudHostView

    /**
     * End Our cloud's engine and stop its computer.
     */
    suspend fun `stopCloudHost`(): CloudHostView

    /**
     * Three word positions (1-based) to ask for after the person wrote the
     * words down.
     */
    fun `backupCheck`(): List<kotlin.UInt>

    /**
     * The 12 words, in order, for Settings > Back up your account. Call
     * only after the person passed the app's Face ID or passcode check.
     */
    fun `backupWords`(): List<kotlin.String>

    /**
     * Check the backup answers; when every one matches, the words are
     * recorded as saved and Settings stops asking.
     */
    fun `confirmBackup`(`answers`: List<WordCheck>): kotlin.Boolean

    /**
     * The account's identity, or `None` until it is loaded on launch.
     */
    fun `identity`(): IdentityView?

    /**
     * Restore from 12 or 24 words, then sign in with their key, which
     * brings back the account they belong to. Refused when this phone's
     * own words aren't backed up yet, unless `replace_unsaved`.
     */
    fun `restoreFromWords`(`words`: kotlin.String, `replaceUnsaved`: kotlin.Boolean): IdentityView

    /**
     * The key alone as `nsec1…`, for other Nostr apps. It can't recover
     * the wallet; the words recover both. Gate it as `backup_words`.
     */
    fun `revealNsec`(): kotlin.String

    /**
     * Use App Attest for this phone's first sign-in. Set it before
     * `start_identity`.
     */
    fun `setAppAttester`(`attester`: AppAttester)

    /**
     * Keep the words in iCloud Keychain (`true`), so a new iPhone on the
     * same Apple account gets them back, or on this phone only (`false`,
     * the default).
     */
    fun `setIcloudCopy`(`on`: kotlin.Boolean)

    /**
     * Set Android's platform provider before `start_identity`. A missing or
     * unavailable provider keeps the proof-of-work path.
     */
    fun `setPlayIntegrityAttester`(`attester`: PlayIntegrityAttester)

    /**
     * Starts this phone's account on launch, with nothing for the person
     * to do: open the 12 words (or reuse the wallet's, or make new ones),
     * then sign in with the key. A phone that was signed in before keeps
     * its account; the new key is added to it.
     */
    fun `startIdentity`(`deviceName`: kotlin.String)

    /**
     * The own-computer card's record for whoever is signed in, or this
     * install while signed out.
     */
    fun `ownComputerOffer`(): CoreOwnComputerOffer

    /**
     * Approve a scanned website login with this phone's identity key: the
     * browser that showed the code signs in as this account. Ask first
     * with [`Self::scanned_login`]. Answers the browser's name.
     */
    suspend fun `approveScannedLogin`(`code`: kotlin.String): kotlin.String

    /**
     * The browser a scanned website login signs in ("Chrome on macOS"),
     * to name in the confirm sheet before approving.
     */
    suspend fun `scannedLogin`(`code`: kotlin.String): kotlin.String

    companion object
}

