public interface CoreSavedHistoryInterface {

    fun `chatHomes`(`client`: CoreClient): CoreChatHomes

    /**
     * Open an account-scoped part that need not be in the current list page.
     */
    fun `openChatPart`(`id`: kotlin.String)

    /**
     * Adds a note to a shown Lab card, at `seconds` into its video when it
     * plays.
     */
    suspend fun `labAddNote`(`card`: kotlin.String, `seconds`: kotlin.Double?, `text`: kotlin.String)

    /**
     * The files a shown Lab card's media cell draws.
     */
    fun `labCard`(`card`: kotlin.String): LabCardFiles?

    /**
     * One of a shown Lab card's files.
     */
    suspend fun `labMedia`(`card`: kotlin.String, `artifact`: kotlin.String): LabMediaFile

    /**
     * The web page a shown Lab card opens, on the chat's own website.
     */
    fun `labPage`(`card`: kotlin.String): kotlin.String?

    /**
     * Shows version `number` in a shown Lab card's row; following then
     * keeps that version current. False when it couldn't be read.
     */
    suspend fun `labShowVersion`(`card`: kotlin.String, `number`: kotlin.ULong): kotlin.Boolean

    /**
     * A shown Lab card's document versions, newest first.
     */
    suspend fun `labVersions`(`card`: kotlin.String): List<LabVersion>

    /**
     * Whether a Lab card row is on screen. A visible card follows its
     * document while the app is in the foreground, so its state and notes
     * stay current.
     */
    fun `labVisible`(`card`: kotlin.String, `visible`: kotlin.Boolean)

    fun `action`(`action`: SavedHistoryAction)

    /**
     * Download only references in the currently authorized transcript.
     */
    suspend fun `attachmentBytes`(`path`: kotlin.String): kotlin.ByteArray

    fun `attachments`(): List<SavedAttachment>

    fun `downloadedFile`(): SavedFileBytes

    fun `downloadedFilePart`(`part`: kotlin.ULong): SavedFilePart

    /**
     * Native view visibility controls following; navigation never grants write access.
     */
    fun `follow`(`visible`: kotlin.Boolean)

    fun `message`(`id`: kotlin.String, `part`: kotlin.ULong): SavedMessagePart

    /**
     * Render account history through the same Rust layout engine as computer sessions.
     */
    fun `renderTranscript`(`view`: TranscriptView)

    fun `setForeground`(`active`: kotlin.Boolean)

    fun `shutdown`()

    fun `snapshot`(): SavedHistorySnapshot

    companion object
}

