    ,
    var `createdAtMs`: kotlin.Long
    ,
    var `unseen`: kotlin.Boolean
    ,
    var `archived`: kotlin.Boolean
    ,
    var `pinned`: kotlin.Boolean
    ,
    var `sectionId`: kotlin.String?
    ,
    var `pullRequest`: PullRequest?
    ,
    /**
     * Oldest unadopted send from this device (open sessions only).
     */
    var `sendState`: SendState?
    ,
    var `parentChatId`: kotlin.String?
    ,
    /**
     * 2 = chat2; 1 = legacy (not dialable).
