/**
 * What a delete request came to.
 */
sealed class AccountDeletion {

    /**
     * The account is gone and the app is signed out.
     */
    object Deleted : AccountDeletion()


    /**
     * Paid credit is left: ask, then call again with `forfeit_balance`.
     */
    data class PaidCredit(
        val `message`: kotlin.String) : AccountDeletion()

    {


        companion object
    }

    /**
     * The person owns a team with other members.
     */
    data class SharedTeam(
        val `message`: kotlin.String) : AccountDeletion()

    {


        companion object
    }

    /**
     * It didn't work; the message says what to do.
     */
    data class Failed(
        val `message`: kotlin.String) : AccountDeletion()

    {


        companion object
    }








    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAccountDeletion : FfiConverterRustBuffer<AccountDeletion>{
    override fun read(buf: ByteBuffer): AccountDeletion {
        return when(buf.getInt()) {
            1 -> AccountDeletion.Deleted
            2 -> AccountDeletion.PaidCredit(
                FfiConverterString.read(buf),
                )
            3 -> AccountDeletion.SharedTeam(
                FfiConverterString.read(buf),
                )
            4 -> AccountDeletion.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AccountDeletion): ULong = when(value) {
        is AccountDeletion.Deleted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is AccountDeletion.PaidCredit -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
        is AccountDeletion.SharedTeam -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
        is AccountDeletion.Failed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

