public object FfiConverterTypeWidgetKind : FfiConverterRustBuffer<WidgetKind>{
    override fun read(buf: ByteBuffer): WidgetKind {
        return when(buf.getInt()) {
            1 -> WidgetKind.CopyCode
            2 -> WidgetKind.Disclosure(
                FfiConverterBoolean.read(buf),
                )
            3 -> WidgetKind.ToolStatus(
                FfiConverterBoolean.read(buf),
                FfiConverterBoolean.read(buf),
                )
            4 -> WidgetKind.Image(
                FfiConverterString.read(buf),
                )
            5 -> WidgetKind.Working(
                FfiConverterOptionalLong.read(buf),
                FfiConverterBoolean.read(buf),
                )
            6 -> WidgetKind.Spinner
            7 -> WidgetKind.Detail(
                FfiConverterString.read(buf),
                )
            8 -> WidgetKind.Icon(
                FfiConverterString.read(buf),
                FfiConverterTypeColorRole.read(buf),
                )
            9 -> WidgetKind.Chevron(
                FfiConverterBoolean.read(buf),
                )
            10 -> WidgetKind.ToolRail(
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterSequenceFloat.read(buf),
                FfiConverterSequenceFloat.read(buf),
                )
            11 -> WidgetKind.ToolToggle(
                FfiConverterULong.read(buf),
                FfiConverterBoolean.read(buf),
                )
            12 -> WidgetKind.Shimmer
            13 -> WidgetKind.Visual(
                FfiConverterString.read(buf),
                )
            14 -> WidgetKind.LabMedia(
                FfiConverterString.read(buf),
                FfiConverterTypeLabMediaView.read(buf),
                )
            15 -> WidgetKind.LabOpen(
                FfiConverterString.read(buf),
                )
            16 -> WidgetKind.LabNote(
                FfiConverterString.read(buf),
                )
            17 -> WidgetKind.LabVersions(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: WidgetKind): ULong = when(value) {
        is WidgetKind.CopyCode -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is WidgetKind.Disclosure -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`expanded`)
            )
        }
        is WidgetKind.ToolStatus -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`running`)
                + FfiConverterBoolean.allocationSize(value.`failed`)
            )
        }
        is WidgetKind.Image -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reference`)
            )
        }
        is WidgetKind.Working -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalLong.allocationSize(value.`sinceMs`)
                + FfiConverterBoolean.allocationSize(value.`streaming`)
            )
        }
        is WidgetKind.Spinner -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is WidgetKind.Detail -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`title`)
            )
        }
        is WidgetKind.Icon -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`name`)
                + FfiConverterTypeColorRole.allocationSize(value.`color`)
            )
        }
        is WidgetKind.Chevron -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`expanded`)
            )
        }
        is WidgetKind.ToolRail -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterFloat.allocationSize(value.`trunkX`)
                + FfiConverterFloat.allocationSize(value.`bend`)
                + FfiConverterFloat.allocationSize(value.`branchEnd`)
                + FfiConverterFloat.allocationSize(value.`rowMid`)
                + FfiConverterSequenceFloat.allocationSize(value.`tops`)
                + FfiConverterSequenceFloat.allocationSize(value.`heights`)
            )
        }
        is WidgetKind.ToolToggle -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`detail`)
                + FfiConverterBoolean.allocationSize(value.`open`)
            )
        }
        is WidgetKind.Shimmer -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is WidgetKind.Visual -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
            )
        }
        is WidgetKind.LabMedia -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`card`)
                + FfiConverterTypeLabMediaView.allocationSize(value.`view`)
            )
        }
        is WidgetKind.LabOpen -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`card`)
            )
        }
        is WidgetKind.LabNote -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`card`)
            )
        }
        is WidgetKind.LabVersions -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`card`)
            )
        }
    }

    override fun write(value: WidgetKind, buf: ByteBuffer) {
        when(value) {
            is WidgetKind.CopyCode -> {
                buf.putInt(1)
                Unit
            }
            is WidgetKind.Disclosure -> {
                buf.putInt(2)
                FfiConverterBoolean.write(value.`expanded`, buf)
                Unit
            }
            is WidgetKind.ToolStatus -> {
                buf.putInt(3)
                FfiConverterBoolean.write(value.`running`, buf)
                FfiConverterBoolean.write(value.`failed`, buf)
                Unit
            }
            is WidgetKind.Image -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reference`, buf)
                Unit
            }
            is WidgetKind.Working -> {
                buf.putInt(5)
                FfiConverterOptionalLong.write(value.`sinceMs`, buf)
                FfiConverterBoolean.write(value.`streaming`, buf)
                Unit
            }
            is WidgetKind.Spinner -> {
                buf.putInt(6)
                Unit
            }
            is WidgetKind.Detail -> {
                buf.putInt(7)
                FfiConverterString.write(value.`title`, buf)
                Unit
            }
            is WidgetKind.Icon -> {
                buf.putInt(8)
                FfiConverterString.write(value.`name`, buf)
                FfiConverterTypeColorRole.write(value.`color`, buf)
                Unit
            }
            is WidgetKind.Chevron -> {
                buf.putInt(9)
                FfiConverterBoolean.write(value.`expanded`, buf)
                Unit
            }
            is WidgetKind.ToolRail -> {
                buf.putInt(10)
                FfiConverterFloat.write(value.`trunkX`, buf)
                FfiConverterFloat.write(value.`bend`, buf)
                FfiConverterFloat.write(value.`branchEnd`, buf)
                FfiConverterFloat.write(value.`rowMid`, buf)
                FfiConverterSequenceFloat.write(value.`tops`, buf)
                FfiConverterSequenceFloat.write(value.`heights`, buf)
                Unit
            }
            is WidgetKind.ToolToggle -> {
                buf.putInt(11)
                FfiConverterULong.write(value.`detail`, buf)
                FfiConverterBoolean.write(value.`open`, buf)
                Unit
            }
            is WidgetKind.Shimmer -> {
                buf.putInt(12)
                Unit
            }
            is WidgetKind.Visual -> {
                buf.putInt(13)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
            is WidgetKind.LabMedia -> {
                buf.putInt(14)
                FfiConverterString.write(value.`card`, buf)
                FfiConverterTypeLabMediaView.write(value.`view`, buf)
                Unit
            }
            is WidgetKind.LabOpen -> {
                buf.putInt(15)
                FfiConverterString.write(value.`card`, buf)
                Unit
            }
            is WidgetKind.LabNote -> {
                buf.putInt(16)
                FfiConverterString.write(value.`card`, buf)
                Unit
            }
            is WidgetKind.LabVersions -> {
                buf.putInt(17)
                FfiConverterString.write(value.`card`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalUInt: FfiConverterRustBuffer<kotlin.UInt?> {
    override fun read(buf: ByteBuffer): kotlin.UInt? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUInt.read(buf)
    }

    override fun allocationSize(value: kotlin.UInt?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UInt?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUInt.write(value, buf)
        }
    }
}




